import re
from html.parser import HTMLParser

BASE = "https://www.ilga.gov"
SEG = "\x01"

class Act(HTMLParser):
    """The full-text page of one act: every <table width=500> in the bill-text box is one ILCS document (a section, or an
    article/title heading). Lines break at <br>/<p>/<center>/<div>; SEG marks the end of each <font> run, which is how the
    page separates 'Sec. 1-2.' from its heading and its heading from its text."""
    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.docs, self.cur, self.depth, self.skip = [], None, 0, 0
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if self.cur is None:
            if tag == "table" and a.get("width") == "500":
                self.cur, self.depth = [], 1
            return
        if tag == "table":
            self.depth += 1
        if tag in ("script", "style"):
            self.skip += 1
        if tag in ("br", "p", "center", "div", "tr"):
            self.cur.append("\n")
    def handle_endtag(self, tag):
        if self.cur is None:
            return
        if tag in ("script", "style") and self.skip:
            self.skip -= 1
        if tag == "font":
            self.cur.append(SEG)
        if tag in ("p", "center", "div", "tr"):
            self.cur.append("\n")
        if tag == "table":
            self.depth -= 1
            if not self.depth:
                self.docs.append("".join(self.cur)); self.cur = None
    def handle_data(self, d):
        if self.cur is not None and not self.skip:
            self.cur.append(re.sub(r"[\r\n\t]+", " ", d.replace("\xa0", " ")))

# a run that reads like a sentence of law is the section's first words, not its heading (2-10.1, 21.2-3, 28-11 have none)
SENTENCE = re.compile(r"^ ?\(|^ ?As used\b| (shall|may|must|means|is|are|will|has|have|does|do|includes)\b")
CITE = re.compile(r"^\((\d+) ILCS ([^)]+)\)")

def _norm(l):
    return " ".join(l.replace(SEG, " ").split())

def act_sections(html):
    i = html.find('id="billtextanchor"')
    p = Act(); p.feed(html[i:] if i >= 0 else html); p.close()
    for d in p.docs:
        lines = [l for l in d.split("\n") if l.replace(SEG, "").strip()]
        if not lines:
            continue
        m = CITE.match(_norm(lines[0]))
        if not m or "heading" in m.group(2):
            continue
        chap, sid = m.group(1), m.group(2).strip()
        body, heading = lines[1:], ""
        at = next((j for j, l in enumerate(body) if re.match(r"^Sec\. [^ ]+\.", _norm(l))), None)
        if at is not None and at <= 2:
            # drop "Sec. N." even when the page splits it over two runs ("Sec." | "1-45. Limitations.")
            line = re.sub(r"^[\s\x01]*Sec\.[\s\x01]*[^\s\x01]+\.", "", body[at])
            segs = [s.strip() for s in line.split(SEG) if s.strip()]
            later = [l for l in body[at + 1:] if not _norm(l).startswith("(Source:")]
            if segs and not SENTENCE.search(" " + segs[0]):
                c = segs[0]
                cut = c.find(".  ")
                if 0 < cut < 250 and " means " not in c[:cut]:
                    # "Obstructing an emergency management worker.  A person who ..." : heading and text in one run
                    heading, segs = c[:cut + 1], [c[cut + 3:]] + segs[1:]
                elif c.endswith((".", ".)")) and " means " not in c and (
                        (len(segs) == 1 and len(c) <= 250 and later) or (len(segs) > 1 and len(c) <= 100)):
                    heading, segs = c, segs[1:]
            heading = " ".join(heading.split())
            body = body[:at] + ([" ".join(segs)] if segs else []) + body[at + 1:]
        text = "\n".join(" ".join(l.replace(SEG, " ").split()) for l in body)
        text = "\n".join(l for l in text.split("\n") if l)
        yield chap, sid, heading.rstrip(), text

def sections():
    k, page = fetch(BASE + "/Legislation/ILCS/Chapters")
    chapters = []
    for h in re.findall(r'href="(/Legislation/ILCS/Acts\?ChapterID=[^"]+)"', page):
        h = h.replace("&amp;", "&").replace(" ", "%20")
        if h not in chapters:
            chapters.append(h)
    log("chapters %d" % len(chapters))
    seen = set()
    for ch in chapters:
        k, page = fetch(BASE + ch)
        acts = []
        # each act row: the Articles link, then its listing text ("720 ILCS 5/ Criminal Code of 2012."); repealed acts are skipped
        for m in re.finditer(r'href="/Legislation/ILCS/Articles\?ActID=(\d+)&(?:amp;)?ChapterID=(\d+)[^"]*"[^>]*>(.*?)</a>', page, re.S):
            label = " ".join(re.sub(r"<[^>]+>", " ", m.group(3)).replace("&nbsp;", " ").split())
            if "(Repealed" in label or m.group(1) in [a[0] for a in acts]:
                continue
            acts.append((m.group(1), m.group(2), label))
        log("%s: %d acts" % (ch.split("&")[1], len(acts)))
        for actid, chapid, label in acts:
            url = "%s/legislation/ILCS/details?ActID=%s&ChapterID=%s&SeqStart=&ChapAct=FullText" % (BASE, actid, chapid)
            try:
                k, html = fetch(url)
            except Exception as e:
                log("act %s (%s) failed: %s" % (actid, label[:40], e)); continue
            n = 0
            for chap, sid, head, text in act_sections(html):
                key = chap + " " + sid
                if key in seen or not text:
                    continue
                seen.add(key); n += 1
                yield {"id": sid, "heading": head, "text": text, "url": url, "vars": {"chapter": chap}}
            if not n:
                log("act %s (%s): no sections" % (actid, label[:50]))
